import { useState } from 'react';
import {
  Badge,
  Divider,
  FormField,
  Heading,
  SegmentedControl,
  Select,
  Slider,
  Stack,
  Switch,
  Text,
} from '@jinx-ui/react';

export type ThemeMode = 'light' | 'dark' | 'system';
export type FontFamily = 'system' | 'inter' | 'mono';

export interface AppearanceSettings {
  theme: ThemeMode;
  scale: number;
  dense: boolean;
  font: FontFamily;
}

export interface AppearanceSettingsScreenProps {
  value?: Partial<AppearanceSettings>;
  onChange?: (value: AppearanceSettings) => void;
}

const DEFAULTS: AppearanceSettings = {
  theme: 'system',
  scale: 100,
  dense: false,
  font: 'system',
};

const THEME_OPTIONS: { value: ThemeMode; label: string }[] = [
  { value: 'light', label: 'Светлая' },
  { value: 'dark', label: 'Тёмная' },
  { value: 'system', label: 'Системная' },
];

const FONT_OPTIONS: { value: FontFamily; label: string }[] = [
  { value: 'system', label: 'Системный' },
  { value: 'inter', label: 'Inter' },
  { value: 'mono', label: 'Монospace' },
];

function AppearanceSettingsScreen({ value, onChange }: AppearanceSettingsScreenProps) {
  const [settings, setSettings] = useState<AppearanceSettings>({ ...DEFAULTS, ...value });

  const update = (patch: Partial<AppearanceSettings>) => {
    const next = { ...settings, ...patch };
    setSettings(next);
    onChange?.(next);
  };

  const themeLabel =
    THEME_OPTIONS.find((option) => option.value === settings.theme)?.label ?? '';

  return (
    <Stack
      direction="column"
      gap="lg"
      className="jx-surface jx-p-lg jx-radius-md"
      style={{ maxWidth: 'var(--jx-size-container-sm)' }}
    >
      <Stack direction="row" align="center" justify="space-between" gap="sm">
        <Heading level={2}>Внешний вид</Heading>
        <Badge variant="neutral">{themeLabel}</Badge>
      </Stack>

      <FormField label="Тема" htmlFor="appearance-theme">
        <SegmentedControl
          id="appearance-theme"
          value={settings.theme}
          options={THEME_OPTIONS}
          onChange={(theme: ThemeMode) => update({ theme })}
        />
      </FormField>

      <FormField label="Масштаб интерфейса" htmlFor="appearance-scale">
        <Stack direction="row" align="center" gap="md">
          <Slider
            id="appearance-scale"
            min={80}
            max={140}
            step={5}
            value={settings.scale}
            onChange={(scale: number) => update({ scale })}
            style={{ flex: 1 }}
          />
          <Text
            variant="body"
            tone="muted"
            style={{ minWidth: 'var(--jx-size-8)', textAlign: 'right' }}
          >
            {settings.scale}%
          </Text>
        </Stack>
      </FormField>

      <Switch
        checked={settings.dense}
        onChange={(dense: boolean) => update({ dense })}
        label="Плотная вёрстка"
        description="Уменьшает отступы между элементами интерфейса."
      />

      <Divider />

      <Stack direction="column" gap="md">
        <Heading level={3}>Ещё</Heading>
        <FormField label="Шрифт" htmlFor="appearance-font">
          <Select
            id="appearance-font"
            value={settings.font}
            options={FONT_OPTIONS}
            onChange={(font: FontFamily) => update({ font })}
          />
        </FormField>
      </Stack>
    </Stack>
  );
}

export default AppearanceSettingsScreen;

